# Daily review component + render
review = r'''
function DailyReviewPanel({ data, identity, onRefresh }: { data: any; identity: Identity; onRefresh: () => void }) {
  const [editing, setEditing] = useState<any | null>(null);
  const [date, setDate] = useState(today());
  const [content, setContent] = useState("");
  const reviews = (data.dailyReviews || []).filter((r: any) => r.reviewerName === identity.name);
  const save = trpc.ops.upsertDailyReview.useMutation({ onSuccess: () => { toast.success(editing ? "日复盘已更新" : "日复盘已保存"); setEditing(null); setDate(today()); setContent(""); onRefresh(); }, onError: e => toast.error(e.message) });
  const remove = trpc.ops.deleteDailyReview.useMutation({ onSuccess: () => { toast.success("日复盘已删除"); onRefresh(); }, onError: e => toast.error(e.message) });
  const beginEdit = (item: any) => { setEditing(item); setDate(item.reviewDate); setContent(item.content); };
  return <div className="soft-card p-4 md:p-5"><SectionTitle eyebrow="PRIVATE DAILY REVIEW" title="我的日复盘" action={<Badge tone="blue">仅本人可见</Badge>} /><p className="mb-3 text-xs text-[#9b8172]">记录当天经营复盘、亮点、问题原因和明日动作，只会显示在自己的工作台。</p><div className="grid gap-3 md:grid-cols-[180px_1fr]"><Field label="复盘日期" value={date} onChange={setDate} type="date" /><label className="block"><span className="mb-1.5 block text-[11px] font-semibold text-[#75594b]">复盘记录</span><textarea value={content} onChange={e => setContent(e.target.value)} placeholder="今天做得好的地方、问题原因、明日改进动作" className="min-h-[100px] w-full rounded-xl border border-[#eadbca] bg-white p-3 text-sm" /></label></div><div className="mt-3 flex gap-2"><button disabled={save.isPending || !content.trim()} onClick={() => save.mutate({ role: "store", identityName: identity.name, storeName: identity.storeName || "", id: editing?.id, reviewDate: date, content: content.trim() })} className="rounded-xl bg-[#6585b7] px-4 py-2 text-xs font-bold text-white disabled:opacity-50">{save.isPending ? "保存中…" : editing ? "保存复盘修改" : "保存日复盘"}</button>{editing && <button onClick={() => { setEditing(null); setDate(today()); setContent(""); }} className="rounded-xl bg-[#f1e4d8] px-4 py-2 text-xs font-bold text-[#987d6e]">取消编辑</button>}</div><div className="mt-4 space-y-2">{reviews.map((item: any) => <div key={item.id} className="rounded-xl border border-[#e5edf8] bg-[#f8fbff] p-3"><div className="flex items-start justify-between gap-2"><div><b className="text-xs text-[#4f6e9e]">{item.reviewDate}</b><p className="mt-1 whitespace-pre-wrap text-xs leading-5 text-[#71574b]">{item.content}</p></div><div className="flex gap-1"><button onClick={() => beginEdit(item)} className="rounded-lg p-2 text-[#6b8dbd]"><Pencil size={14} /></button><button onClick={() => window.confirm("确认删除这条日复盘吗？") && remove.mutate({ role: "store", identityName: identity.name, storeName: identity.storeName || "", id: item.id })} className="rounded-lg p-2 text-[#c8786a]"><Trash2 size={14} /></button></div></div></div>)}</div></div>;
}
'''
