# Weekly touch tooltip for bar values
p = p.replace('''  const max = Math.max(1, ...bars.map(b => b.value));\n  return <div''', '''  const max = Math.max(1, ...bars.map(b => b.value));\n  const [selectedBar, setSelectedBar] = useState<any | null>(null);\n  return <div''')
p = p.replace('''<div className="w-full max-w-[34px] rounded-t-xl bg-gradient-to-t from-[#df7d46] to-[#f5be7b] transition-all" style={{ height: `${Math.max(8, bar.value / max * 125)}px` }} title={money(bar.value)} />''', '''<button onClick={() => setSelectedBar(bar)} className="relative w-full max-w-[34px] rounded-t-xl bg-gradient-to-t from-[#df7d46] to-[#f5be7b] transition-all hover:brightness-110" style={{ height: `${Math.max(8, bar.value / max * 125)}px` }} title={`${bar.date} 实收 ${money(bar.value)}`} aria-label={`${bar.date} 实收 ${money(bar.value)}`} />''')
p = p.replace('''</div></div><div className="soft-card p-5"><SectionTitle eyebrow="TARGET TRACKING"''', '''</div>{selectedBar && <div className="mt-3 rounded-xl bg-[#fff1df] p-3 text-xs text-[#8f5f3e]">{selectedBar.date} 实收：<b>{money(selectedBar.value)}</b>（点击其他柱子可切换）</div>}</div><div className="soft-card p-5"><SectionTitle eyebrow="TARGET TRACKING"''', 1)
home.write_text(p)
print('extended schema, router, and UI')
